"""``RaftWrapper``: drives RAFT, an external wellbore and rock simulator, one tango timestep at a time.

RAFT (GEG-ETHZ/RAFT, the optional ``raft`` extra) solves flow and heat in
a well embedded in a 3D finite-element model of the surrounding rock. Its
coupling API (``geg_raft.api.RaftModel``) advances a *trial* state from the
last accepted state, as often as needed, until the caller accepts it. That
matches tango's injection-enthalpy iteration, which re-solves each timestep
until the loop closes and then moves on:

- ``solve()`` runs one trial for the current timestep. tango restores each
  component's ``state`` before every re-solve, and RAFT restarts every
  trial from its own accepted state, so a re-solve needs nothing restored
  on RAFT's side.
- ``accept()`` keeps the last trial. ``GroupedSubsurfaceComponent``'s
  ``accept_timestep`` calls it once per timestep, after the final solve.

RAFT works in pressure, temperature and mass flow; tango's streams carry
enthalpy. The wrapper converts with tango's own fluid properties
(``FluidState``, ``common.fluid_name``/``coolprop_backend``). The loop's
pressure is set at its inlet, as everywhere in tango: RAFT gets the inlet
pressure and temperature and the outlet mass flow, and returns the outlet
pressure and temperature. Mass flow is assumed constant around the loop
(a sealed well), and a RAFT result that breaks this raises.

The ``raft:`` block of a tango config is this object. ``template`` names a
RAFT config file, made by hand together with its mesh (meshes are never
generated by tango). The template's rock properties, initial temperature
profile, fluid and well alignment are checked against the tango config
(they must agree; neither silently overrides the other). The wrapper then
sets what tango owns: the well diameter and roughness, the coupling
boundary conditions and the output location.

``state``/``history`` record, per timestep, RAFT's raw values at the well
inlet and outlet, how much work the timestep took (trial solves, wall
time), and RAFT's own timestepping statistics for the accepted trial
(``RaftModel.solve_stats``).
"""

from __future__ import annotations

import atexit
import copy
import math
import shutil
import tempfile
import time
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Literal

import yaml
from pydantic import BaseModel, ConfigDict, Field, PrivateAttr

from tango.core.errors import ConfigError, ConvergenceError, SaturationError
from tango.core.fluid_state import FluidState
from tango.core.locked_state import LockedState
from tango.core.specs import Common
from tango.core.state_methods import StateMethods
from tango.core.stream import Stream

RAFT_FLUID_TYPES: dict[str, str] = {"H2O": "Water"}
"""tango ``common.fluid_name`` -> RAFT ``material.fluid.fluid_type``, for the fluids the wrapper supports."""

_REL_TOL = 1e-9
"""Relative tolerance for a template value to count as agreeing with the tango config."""

_MASS_RATE_REL_TOL = 1e-3
"""Relative tolerance for RAFT's reported well flows to count as the loop's mass rate.

The flow RAFT solves for at the pressure-controlled inlet matches the
outlet's only approximately: by ~1e-6 relative in RAFT's AGS example's first
years, growing to ~2e-4 later in the run. Fluid actually lost to the rock
would show up as far more than this. RAFT's inlet flow is recorded in
``RaftWrapperState.mass_rate_inlet``."""


def _raft_model_class() -> Any:
    """Return ``geg_raft.api.RaftModel``, importing RAFT only when a RAFT run actually starts.

    Raises:
        ConfigError: RAFT is not installed.
    """
    try:
        from geg_raft.api import RaftModel  # noqa: PLC0415 -- optional dependency
    except ImportError as exc:
        raise ConfigError(
            "grouped_subsurface variant 'raft' needs the optional RAFT dependency: "
            "run `just setup-raft` (or `uv sync --extra raft`).",
        ) from exc
    return RaftModel


def _raft_timestep_error() -> type[Exception]:
    """Return ``geg_raft.subsurface.TimestepError`` (RAFT failed to converge at its minimum timestep)."""
    from geg_raft.subsurface import TimestepError  # noqa: PLC0415 -- optional dependency

    return TimestepError


def _ls_nan() -> LockedState[float]:
    ls: LockedState[float] = LockedState(float("nan"))
    ls.mark_stale()
    return ls


def _ls_list() -> LockedState[list[float]]:
    ls: LockedState[list[float]] = LockedState([])
    ls.mark_stale()
    return ls


@dataclass(frozen=True)
class RaftWrapperState(StateMethods):
    """RAFT's values for one tango timestep, as RAFT reports them."""

    P_inlet: LockedState[float] = field(default_factory=_ls_nan)
    """Pressure (Pa) at the well inlet (set by tango)."""
    T_inlet: LockedState[float] = field(default_factory=_ls_nan)
    """Temperature (K) at the well inlet (set by tango)."""
    mass_rate_inlet: LockedState[float] = field(default_factory=_ls_nan)
    """Mass flow (kg/s) into the well inlet, solved by RAFT."""
    P_outlet: LockedState[float] = field(default_factory=_ls_nan)
    """Pressure (Pa) at the well outlet, solved by RAFT."""
    T_outlet: LockedState[float] = field(default_factory=_ls_nan)
    """Temperature (K) at the well outlet, solved by RAFT."""
    mass_rate_outlet: LockedState[float] = field(default_factory=_ls_nan)
    """Mass flow (kg/s) out of the well outlet (set by tango)."""
    trial_solves: LockedState[float] = field(default_factory=_ls_nan)
    """RAFT solves this timestep took, one per tango injection-enthalpy iteration."""
    solve_seconds: LockedState[float] = field(default_factory=_ls_nan)
    """Wall time (s) of all of this timestep's RAFT solves."""
    accepted_steps: LockedState[float] = field(default_factory=_ls_nan)
    """Internal timesteps RAFT took in the accepted trial."""
    attempts: LockedState[float] = field(default_factory=_ls_nan)
    """Internal timestep solves in the accepted trial, rejected ones included."""
    cut_extrapolation: LockedState[float] = field(default_factory=_ls_nan)
    """Internal timesteps in the accepted trial that RAFT rejected for temperature extrapolation error."""
    cut_newton: LockedState[float] = field(default_factory=_ls_nan)
    """Internal timesteps in the accepted trial that RAFT rejected because Newton-Raphson failed."""
    constraint_switches: LockedState[float] = field(default_factory=_ls_nan)
    """Extra solves in the accepted trial after a wellbore constraint switched."""
    dt_min_proceeds: LockedState[float] = field(default_factory=_ls_nan)
    """Internal timesteps in the accepted trial that RAFT accepted at ``timestep_min`` with an error above
    its tolerance."""
    dt_accepted: LockedState[list[float]] = field(default_factory=_ls_list)
    """Size (s) of each internal timestep RAFT took in the accepted trial, in order; they add up to the
    tango timestep."""


@dataclass
class RaftWrapperHistory:
    """Per-timestep history of ``RaftWrapperState``, one list per field."""

    P_inlet: list[float] = field(default_factory=list)
    T_inlet: list[float] = field(default_factory=list)
    mass_rate_inlet: list[float] = field(default_factory=list)
    P_outlet: list[float] = field(default_factory=list)
    T_outlet: list[float] = field(default_factory=list)
    mass_rate_outlet: list[float] = field(default_factory=list)
    trial_solves: list[float] = field(default_factory=list)
    solve_seconds: list[float] = field(default_factory=list)
    accepted_steps: list[float] = field(default_factory=list)
    attempts: list[float] = field(default_factory=list)
    cut_extrapolation: list[float] = field(default_factory=list)
    cut_newton: list[float] = field(default_factory=list)
    constraint_switches: list[float] = field(default_factory=list)
    dt_min_proceeds: list[float] = field(default_factory=list)
    dt_accepted: list[list[float]] = field(default_factory=list)

    def record(self, state: RaftWrapperState) -> None:
        """Append ``state`` as one timestep entry."""
        self.P_inlet.append(state.P_inlet.get_fresh())
        self.T_inlet.append(state.T_inlet.get_fresh())
        self.mass_rate_inlet.append(state.mass_rate_inlet.get_fresh())
        self.P_outlet.append(state.P_outlet.get_fresh())
        self.T_outlet.append(state.T_outlet.get_fresh())
        self.mass_rate_outlet.append(state.mass_rate_outlet.get_fresh())
        self.trial_solves.append(state.trial_solves.get_fresh())
        self.solve_seconds.append(state.solve_seconds.get_fresh())
        self.accepted_steps.append(state.accepted_steps.get_fresh())
        self.attempts.append(state.attempts.get_fresh())
        self.cut_extrapolation.append(state.cut_extrapolation.get_fresh())
        self.cut_newton.append(state.cut_newton.get_fresh())
        self.constraint_switches.append(state.constraint_switches.get_fresh())
        self.dt_min_proceeds.append(state.dt_min_proceeds.get_fresh())
        self.dt_accepted.append(list(state.dt_accepted.get_fresh()))


@dataclass(frozen=True)
class LoopGeometry:
    """The tango side of the well RAFT simulates: an injection well, a horizontal well and a production well."""

    injection_length: float
    """Vertical injection well length (m)."""
    horizontal_length: float
    """Horizontal well length (m)."""
    production_length: float
    """Vertical production well length (m)."""
    diameter: float
    """Inner diameter (m), the same along the whole loop."""
    pipe_roughness: float
    """Absolute wall roughness (m), the same along the whole loop."""


@dataclass(frozen=True)
class RaftLoopResult:
    """What one RAFT solve gives the loop component, in tango's terms."""

    T_inlet: float
    """Inlet temperature (K) sent to RAFT."""
    P_outlet: float
    """Outlet pressure (Pa)."""
    T_outlet: float
    """Outlet temperature (K)."""
    h_outlet: float
    """Outlet specific enthalpy (J/kg), from (``P_outlet``, ``T_outlet``) with tango's fluid properties."""


class RaftWrapper(BaseModel, StateMethods):
    """The ``raft:`` config block, and the RAFT model it drives. See the module docstring."""

    model_config = ConfigDict(arbitrary_types_allowed=True, extra="forbid")

    template: str = Field(frozen=True)
    """Path to the RAFT config template (absolute, or relative to the working
    directory). Its ``mesh.file`` is resolved relative to the template's own
    directory; a mesh stored with DVC needs ``dvc pull`` first."""
    verbosity: Literal["quiet", "lite", "full"] = Field(default="quiet", frozen=True)
    """RAFT's own console output."""

    state: RaftWrapperState = Field(default_factory=RaftWrapperState)
    history: RaftWrapperHistory = Field(default_factory=RaftWrapperHistory)

    # RAFT config built from the template by prepare(); the RAFT model is
    # started from it on the first solve(), in a fresh temporary directory.
    _raft_config: dict[str, Any] | None = PrivateAttr(default=None)
    _mesh_path: Path | None = PrivateAttr(default=None)
    _common: Common | None = PrivateAttr(default=None)
    _inlet_label: str = PrivateAttr(default="")
    _outlet_label: str = PrivateAttr(default="")
    _model: Any = PrivateAttr(default=None)
    _run_dir: Path | None = PrivateAttr(default=None)
    # Time (s) of RAFT's accepted state, and the end time of the pending trial.
    _accepted_time_seconds: float = PrivateAttr(default=0.0)
    _trial_end_seconds: float | None = PrivateAttr(default=None)
    # Work done since the last accept(); written into state by accept().
    _trial_solves: int = PrivateAttr(default=0)
    _solve_seconds: float = PrivateAttr(default=0.0)

    # ------------------------------------------------------------------
    # Setup
    # ------------------------------------------------------------------

    def prepare(self, common: Common, geometry: LoopGeometry) -> None:
        """Load the template, check it against the tango config, and set what tango owns.

        Raises:
            ConfigError: The template is missing or malformed, or disagrees
                with the tango config (fluid, rock properties, initial
                temperature profile, well alignment).
        """
        template_path = Path(self.template)
        if not template_path.is_file():
            raise ConfigError(
                f"raft.template {self.template!r} not found (absolute, or relative to the working "
                f"directory {Path.cwd()}).",
            )
        config: dict[str, Any] = yaml.safe_load(template_path.read_text())
        try:
            _check_site(config, common, self.template)
            _check_alignment(config, geometry, self.template)
            mesh_path = (template_path.parent / config["mesh"]["file"]).resolve()
            wells = config["material"]["wells"]
            inlet_bc, outlet_bc = _well_end_groups(config, self.template)
        except KeyError as exc:
            raise ConfigError(f"raft.template {self.template!r} has no {exc} entry.") from exc

        wells["diameter"] = [geometry.diameter]
        wells["roughness"] = [geometry.pipe_roughness]
        inlet_bc.setdefault("label", "inlet")
        outlet_bc.setdefault("label", "outlet")
        inlet_bc["hydraulics"] = {"type": "pressure", "function": "external"}
        inlet_bc["thermal"] = {"type": "temperature", "function": "external"}
        outlet_bc["hydraulics"] = {"type": "flux", "function": "external"}
        outlet_bc.pop("thermal", None)
        config["simulation"]["output_vtk"] = 0

        self._raft_config = config
        self._mesh_path = mesh_path
        self._common = common
        self._inlet_label = inlet_bc["label"]
        self._outlet_label = outlet_bc["label"]

    def _start(self) -> None:
        """Write the RAFT config into a fresh temporary directory and start RAFT.

        The directory (RAFT's config, logs and output) is deleted when the
        Python process exits.

        Raises:
            ConfigError: The template's mesh file is missing (a mesh stored
                with DVC needs ``dvc pull``).
        """
        assert self._raft_config is not None and self._mesh_path is not None  # noqa: S101 -- prepare() ran
        if not self._mesh_path.is_file():
            raise ConfigError(
                f"RAFT mesh {self._mesh_path} (from raft.template {self.template!r}) not found. If it's "
                "stored with DVC, run `dvc pull <mesh>.dvc`.",
            )
        run_dir = Path(tempfile.mkdtemp(prefix="tango_raft_"))
        atexit.register(shutil.rmtree, run_dir, ignore_errors=True)
        config = copy.deepcopy(self._raft_config)
        config["mesh"]["file"] = str(self._mesh_path)
        config["simulation"]["output_directory"] = str(run_dir / "output")
        (run_dir / "raft.yaml").write_text(yaml.safe_dump(config, sort_keys=False))
        self._run_dir = run_dir
        self._model = _raft_model_class()("raft.yaml", 0.0, config_dir=run_dir, verbosity=self.verbosity)

    # ------------------------------------------------------------------
    # Coupling
    # ------------------------------------------------------------------

    def solve(self, inlet: Stream, dt_seconds: float) -> RaftLoopResult:
        """Run one RAFT trial over the next ``dt_seconds`` from RAFT's accepted state; fill ``state``.

        Raises:
            ConvergenceError: RAFT failed to converge at its minimum timestep.
            ConfigError: RAFT's result breaks the loop's assumptions (the
                mass flow differs between inlet and outlet, or a boundary
                condition switched mode).
            SaturationError: The outlet state is not liquid, which RAFT's
                single-phase model can't represent.
        """
        if self._model is None:
            self._start()
        assert self._common is not None  # noqa: S101 -- prepare() ran
        fluid, backend = self._common.fluid_name, self._common.coolprop_backend
        P_inlet = inlet.P.get_fresh()
        mass_rate = inlet.mass_rate.get_fresh()
        T_inlet = FluidState.with_HP(fluid, inlet.h.get_fresh(), P_inlet, backend).T
        bcs = {
            self._inlet_label: {"p": P_inlet, "T": T_inlet, "q": mass_rate},
            self._outlet_label: {"p": P_inlet, "T": T_inlet, "q": -mass_rate},
        }

        t_start = self._accepted_time_seconds
        t_end = t_start + dt_seconds
        started = time.perf_counter()
        try:
            result = self._model.solve(t_start, t_end, bcs)
        except _raft_timestep_error() as exc:
            raise ConvergenceError(
                f"RAFT failed to converge between t = {t_start:.6g} s and {t_end:.6g} s with inlet "
                f"P = {P_inlet:.6g} Pa, T = {T_inlet:.6g} K and mass rate {mass_rate:.6g} kg/s: {exc}",
            ) from exc
        self._solve_seconds += time.perf_counter() - started
        self._trial_solves += 1
        self._trial_end_seconds = t_end

        inlet_result, outlet_result = result[self._inlet_label], result[self._outlet_label]
        _check_flow(inlet_result, outlet_result, mass_rate, t_start, t_end)
        P_outlet, T_outlet = float(outlet_result["p"]), float(outlet_result["T"])
        _check_liquid(fluid, P_outlet, T_outlet, backend)
        outlet_state = FluidState.with_PT(fluid, P_outlet, T_outlet, backend)

        s = self.state
        s.P_inlet.update(float(inlet_result["p"]))
        s.T_inlet.update(float(inlet_result["T"]))
        s.mass_rate_inlet.update(float(inlet_result["q"]))
        s.P_outlet.update(P_outlet)
        s.T_outlet.update(T_outlet)
        s.mass_rate_outlet.update(-float(outlet_result["q"]))
        stats = self._model.solve_stats
        s.accepted_steps.update(float(stats.accepted_steps))
        s.attempts.update(float(stats.attempts))
        s.cut_extrapolation.update(float(stats.cut_extrapolation))
        s.cut_newton.update(float(stats.cut_newton))
        s.constraint_switches.update(float(stats.constraint_switches))
        s.dt_min_proceeds.update(float(stats.dt_min_proceeds))
        s.dt_accepted.update([float(dt) for dt in stats.dt_accepted])
        return RaftLoopResult(T_inlet=T_inlet, P_outlet=P_outlet, T_outlet=T_outlet, h_outlet=outlet_state.H)

    def accept(self) -> None:
        """Keep RAFT's last trial as its accepted state, and record this timestep's work in ``state``."""
        if self._model is None or self._trial_end_seconds is None:
            raise RuntimeError("RaftWrapper.accept() called with no RAFT trial to accept.")
        self._model.get_fresh()
        self._accepted_time_seconds = self._trial_end_seconds
        self._trial_end_seconds = None
        self.state.trial_solves.update(float(self._trial_solves))
        self.state.solve_seconds.update(self._solve_seconds)
        self._trial_solves = 0
        self._solve_seconds = 0.0


# ----------------------------------------------------------------------
# Template checks
# ----------------------------------------------------------------------


def _agrees(given: Any, expected: float) -> bool:
    values = given if isinstance(given, list) else [given]
    return all(math.isclose(float(v), expected, rel_tol=_REL_TOL) for v in values)


def _check_site(config: dict[str, Any], common: Common, template: str) -> None:
    """Raise if the template's fluid, rock properties or initial temperature profile differ from ``common``."""
    expected_fluid = RAFT_FLUID_TYPES.get(common.fluid_name)
    if expected_fluid is None:
        raise ConfigError(
            f"grouped_subsurface variant 'raft' supports fluid_name {sorted(RAFT_FLUID_TYPES)}, "
            f"not {common.fluid_name!r}.",
        )
    fluid_type = str(config["material"]["fluid"]["fluid_type"])
    mismatches = (
        []
        if fluid_type.lower() == expected_fluid.lower()
        else [f"fluid_type {fluid_type!r} vs {expected_fluid!r}"]
    )
    solid = config["material"]["solid"]
    initial = config["initial_conditions"]
    pairs = [
        ("material.solid.density", solid["density"], "rock_density", common.rock_density),
        ("material.solid.specific_heat", solid["specific_heat"], "rock_cp", common.rock_cp),
        ("material.solid.therm_cond", solid["therm_cond"], "rock_k", common.rock_k),
        ("initial_conditions.T_ini", initial["T_ini"], "surface_temperature", common.surface_temperature),
        ("initial_conditions.T_grad", initial["T_grad"], "thermal_gradient", common.thermal_gradient),
    ]
    mismatches += [
        f"{raft_key} = {given} vs common.{tango_key} = {expected:g}"
        for raft_key, given, tango_key, expected in pairs
        if not _agrees(given, expected)
    ]
    if mismatches:
        raise ConfigError(
            f"raft.template {template!r} disagrees with the tango config: {'; '.join(mismatches)}. "
            "Both describe the same site; make them agree.",
        )


def _segment_length(segment: list[list[float]]) -> float:
    start, end = segment
    return math.dist(start, end)


def _check_alignment(config: dict[str, Any], geometry: LoopGeometry, template: str) -> None:
    """Raise unless the template has one well whose three segments match the loop's lengths.

    The mesh is built around that alignment, so tango's geometry must be the
    template's: a different geometry needs a new mesh (and template).
    """
    wells = config["mesh"]["wells"]
    if len(wells) != 1 or len(wells[0]["alignment"]) != 3:
        raise ConfigError(
            f"raft.template {template!r} must have one well with three alignment segments "
            "(injection, horizontal, production).",
        )
    template_lengths = [_segment_length(segment) for segment in wells[0]["alignment"]]
    tango_lengths = [geometry.injection_length, geometry.horizontal_length, geometry.production_length]
    if not all(
        math.isclose(a, b, rel_tol=_REL_TOL) for a, b in zip(template_lengths, tango_lengths, strict=True)
    ):
        raise ConfigError(
            f"raft.template {template!r} has well segments of {template_lengths} m, but the tango config's "
            f"injection, horizontal and production wells are {tango_lengths} m. RAFT's mesh is built for "
            "the template's geometry; a different geometry needs a new mesh and template.",
        )


def _well_end_groups(config: dict[str, Any], template: str) -> tuple[dict[str, Any], dict[str, Any]]:
    """Return the template's boundary-condition groups at the well's inlet and outlet."""
    ends: dict[str, dict[str, Any]] = {}
    for group in config["boundary_conditions"]:
        well = group.get("well")
        if well is not None and int(well[0]) == 0:
            ends[str(well[1])] = group
    if set(ends) != {"inlet", "outlet"}:
        raise ConfigError(
            f"raft.template {template!r} needs boundary-condition groups at the well's inlet and outlet "
            '(`well: [0, "inlet"]` and `well: [0, "outlet"]`).',
        )
    return ends["inlet"], ends["outlet"]


# ----------------------------------------------------------------------
# Result checks
# ----------------------------------------------------------------------


def _check_flow(
    inlet_result: dict[str, Any],
    outlet_result: dict[str, Any],
    mass_rate: float,
    t_start: float,
    t_end: float,
) -> None:
    """Raise unless RAFT kept the inlet at fixed pressure and the outlet at fixed flow, both carrying ``mass_rate``."""
    if inlet_result["mode"] != "pressure" or outlet_result["mode"] != "flux":
        raise ConfigError(
            f"RAFT switched the well boundary conditions (inlet mode {inlet_result['mode']!r}, outlet "
            f"mode {outlet_result['mode']!r}; expected 'pressure' and 'flux'); remove pressure "
            "constraints from the template's well groups.",
        )
    for name, q in (("inlet", float(inlet_result["q"])), ("outlet", -float(outlet_result["q"]))):
        if not math.isclose(q, mass_rate, rel_tol=_MASS_RATE_REL_TOL):
            raise ConfigError(
                f"Between t = {t_start:.6g} s and {t_end:.6g} s, RAFT's well {name} carries {q!r} kg/s but the "
                f"loop's mass rate is {mass_rate!r} kg/s: "
                "mass flow must be constant around the loop (a sealed well, perforation_conductance 0).",
            )


def _check_liquid(fluid: str, P: float, T: float, backend: str) -> None:
    """Raise ``SaturationError`` if (``P``, ``T``) is not a compressed liquid (RAFT models single-phase liquid)."""
    saturation_temperature = FluidState.with_PQ(fluid, P, 0.0, backend).T
    if saturation_temperature <= T:
        raise SaturationError(
            f"RAFT's well outlet at {P:.6g} Pa and {T:.6g} K is at or above saturation "
            f"({saturation_temperature:.6g} K); RAFT's single-phase model can't represent boiling.",
        )
